import sys

from durations import format_duration, parse_duration


def main():
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            total += parse_duration(line)
        except ValueError:
            print(f"invalid duration: {line!r}", file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())
